ext('c11_math_ch9',[
C("📍","निर्देशांक और खंड सूत्र",["बिंदु (x, y)","आंतरिक विभाजन अनुपात m : n","x = (m·x₂ + n·x₁)/(m + n)","y = (m·y₂ + n·y₁)/(m + n)"],"किसी रेखाखंड को m अनुपात n में अंदर से बाँटने वाले बिंदु के निर्देशांक खंड सूत्र से मिलते हैं। एक्स बराबर एम गुणा एक्स दो जमा एन गुणा एक्स एक, पूरा भाग एम जमा एन। वाई के लिए भी यही सूत्र चलता है। जब अनुपात एक है, तो यही मध्य बिंदु सूत्र बन जाता है। यह सूत्र त्रिभुज का केंद्रक और रेखा को बाँटने जैसे प्रश्नों में बहुत काम आता है।"),
Q("(1, 2) और (7, 8) को जोड़ने वाले रेखाखंड को 1 : 2 में बाँटने वाले बिंदु के निर्देशांक ज्ञात कीजिए।","x = (1·7 + 2·1)/3 = 3, y = (1·8 + 2·2)/3 = 4, बिंदु (3, 4)","सूत्र लगाइए... एम एक और एन दो है। एक्स बराबर एक गुणा सात जमा दो गुणा एक, भाग तीन। यानी सात जमा दो भाग तीन, यानी तीन। वाई बराबर एक गुणा आठ जमा दो गुणा दो, भाग तीन, यानी बारह भाग तीन, यानी चार। इसलिए बिंदु तीन, चार है।"),
C("📐","ढाल के विभिन्न रूप",["ढाल m = tan θ","m = (y₂ − y₁)/(x₂ − x₁)","क्षैतिज रेखा: m = 0","ऊर्ध्वाधर रेखा: ढाल अपरिभाषित"],"रेखा की ढाल बताती है कि वह कितनी तिरछी है। यह रेखा के धन एक्स अक्ष से बनाए कोण थीटा के टैन के बराबर होती है। दो बिंदुओं से ढाल निकालने के लिए वाई का अंतर भाग एक्स का अंतर लेते हैं। क्षैतिज रेखा की ढाल शून्य होती है क्योंकि वाई का अंतर शून्य है। ऊर्ध्वाधर रेखा में एक्स का अंतर शून्य होता है, इसलिए ढाल अपरिभाषित है। यही कारण है कि एक्स बराबर पाँच जैसी रेखा की ढाल शून्य नहीं, बल्कि अपरिभाषित होती है।"),
Q("30° कोण बनाने वाली रेखा की ढाल क्या होगी?","m = tan 30° = 1/√3","सोचिए... ढाल बराबर टैन थीटा। यहाँ थीटा तीस अंश है, और टैन तीस अंश का मान एक भाग रूट तीन है। यानी लगभग शून्य दशमलव पाँच सात सात। कोण छोटा है तो ढाल भी छोटी होती है।"),
Q("तीन बिंदु A(1, 1), B(2, 3) और C(3, 5) संरेख हैं या नहीं?","AB की ढाल = 2, BC की ढाल = 2। ढालें बराबर हैं, इसलिए संरेख हैं","तीन बिंदु तब एक रेखा में होते हैं जब किन्हीं दो जोड़ों की ढाल बराबर हो। ए बी की ढाल, तीन ऋण एक भाग दो ऋण एक, यानी दो। बी सी की ढाल पाँच ऋण तीन भाग तीन ऋण दो, यानी दो। ढालें बराबर हैं और बिंदु बी उभयनिष्ठ है, इसलिए तीनों बिंदु संरेख हैं।"),
C("↗️","समांतर और लंब रेखाओं की शर्त",["समांतर: m₁ = m₂","लंब: m₁ × m₂ = −1","अक्ष के समांतर विशेष","ढाल का ऋणात्मक व्युत्क्रम"],"दो रेखाएँ समांतर होती हैं यदि उनकी ढाल बराबर हो। वे एक-दूसरे पर लंब होती हैं यदि ढालों का गुणनफल ऋण एक हो। दूसरे शब्दों में, एक की ढाल का ऋणात्मक व्युत्क्रम दूसरी की ढाल है। जैसे ढाल दो की रेखा पर लंब रेखा की ढाल ऋण आधा होगी। ध्यान रखिए कि अक्षों के समांतर और लंब रेखाओं के लिए यह सूत्र अलग ढंग से देखना पड़ता है, क्योंकि एक की ढाल शून्य और दूसरी की अपरिभाषित है।"),
Q("2x + 3y = 6 पर लंब रेखा की ढाल क्या होगी?","दी रेखा की ढाल −2/3, लंब की ढाल 3/2","पहले दी हुई रेखा को वाई बराबर के रूप में लिखिए। तीन वाई बराबर छह ऋण दो एक्स, इसलिए वाई बराबर ऋण दो बटा तीन एक्स जमा दो। ढाल ऋण दो बटा तीन है। लंब रेखा की ढाल उसका ऋणात्मक व्युत्क्रम, यानी तीन बटा दो।"),
Q("(2, 1) से गुज़रने वाली और 3x − y = 5 के समांतर रेखा का समीकरण बताइए।","ढाल = 3। y − 1 = 3(x − 2) ⇒ 3x − y − 5 = 0","पहले दी हुई रेखा की ढाल निकालिए। वाई बराबर तीन एक्स ऋण पाँच, यानी ढाल तीन। समांतर रेखा की ढाल भी तीन होगी। अब बिंदु-ढाल रूप लगाइए। वाई ऋण एक बराबर तीन गुणा एक्स ऋण दो। खोलने पर तीन एक्स ऋण वाई ऋण पाँच बराबर शून्य। यह रेखा दी हुई रेखा के समांतर है।"),
C("🧮","रेखा के समीकरण: सारांश",["ढाल-अंतःखंड: y = mx + c","बिंदु-ढाल: y − y₁ = m(x − x₁)","द्वि-बिंदु रूप","अंतःखंड रूप: x/a + y/b = 1"],"अब रेखा के समीकरणों के चारों रूप एक नज़र में देखिए। ढाल-अंतःखंड रूप में वाई बराबर एम एक्स जमा सी, जहाँ सी वाई-अंतःखंड है। बिंदु-ढाल रूप में बिंदु और ढाल दी हो। द्वि-बिंदु रूप में दो बिंदु दिए हों तो पहले ढाल निकालकर बिंदु-ढाल रूप लगाते हैं। अंतःखंड रूप में एक्स भाग ए जमा वाई भाग बी बराबर एक, जहाँ ए और बी अक्षों पर कटे अंतःखंड हैं। प्रश्न देखकर सही रूप चुनना ही असली कला है।"),
Q("x-अंतःखंड 3 और y-अंतःखंड 4 वाली रेखा का समीकरण लिखिए।","x/3 + y/4 = 1 ⇒ 4x + 3y = 12","अंतःखंड रूप सीधा लगाइए। एक्स भाग तीन जमा वाई भाग चार बराबर एक। दोनों ओर बारह से गुणा कीजिए। चार एक्स जमा तीन वाई बराबर बारह। यही रेखा का समीकरण है। यह एक्स अक्ष को तीन पर और वाई अक्ष को चार पर काटती है।"),
C("🧭","रेखा को मानक रूप में बदलना",["Ax + By + C = 0","ढाल = −A/B","y-अंतःखंड = −C/B","अभिलम्ब रूप: x cos α + y sin α = p"],"व्यापक रूप ए एक्स जमा बी वाई जमा सी बराबर शून्य सबसे आम रूप है। इससे ढाल निकालने का सूत्र है ऋण ए भाग बी। वाई-अंतःखंड ऋण सी भाग बी और एक्स-अंतःखंड ऋण सी भाग ए होता है। अभिलम्ब रूप में मूल बिंदु से रेखा की लंब दूरी पी और अभिलम्ब का कोण अल्फा दिए जाते हैं। यह रूप दूरी के प्रश्नों में सहायक है।"),
Q("4x − 2y + 7 = 0 की ढाल और y-अंतःखंड ज्ञात कीजिए।","ढाल = −A/B = −4/(−2) = 2; y-अंतःखंड = −C/B = −7/(−2) = 7/2","सूत्र लगाइए। यहाँ ए चार, बी ऋण दो और सी सात है। ढाल ऋण ए भाग बी, यानी ऋण चार भाग ऋण दो, यानी दो। वाई-अंतःखंड ऋण सी भाग बी, यानी ऋण सात भाग ऋण दो, यानी साढ़े तीन। चिह्नों पर ध्यान रखिए।"),
C("📏","बिंदु से रेखा की दूरी",["d = |Ax₁ + By₁ + C| / √(A² + B²)","समांतर रेखाओं के बीच दूरी","मापांक का उपयोग","दूरी सदैव धनात्मक"],"बिंदु एक्स एक, वाई एक से रेखा ए एक्स जमा बी वाई जमा सी बराबर शून्य की लंब दूरी इस सूत्र से मिलती है। ए एक्स एक जमा बी वाई एक जमा सी का मापांक, भाग ए वर्ग जमा बी वर्ग का वर्गमूल। मापांक के कारण दूरी हमेशा धनात्मक आती है। दो समांतर रेखाओं के बीच की दूरी निकालने के लिए एक रेखा पर कोई भी बिंदु लीजिए और वही सूत्र दूसरी रेखा पर लगाइए। या सीधा सूत्र सी एक ऋण सी दो का मापांक भाग रूट ए वर्ग जमा बी वर्ग।"),
Q("समांतर रेखाओं 3x + 4y = 5 और 3x + 4y = 15 के बीच की दूरी ज्ञात कीजिए।","d = |15 − 5| / √(9 + 16) = 10/5 = 2","दोनों रेखाओं में एक्स और वाई के गुणांक बराबर हैं, यानी तीन और चार। अंतर दस है और छोर पर वर्गमूल पच्चीस का, यानी पाँच। दस भाग पाँच बराबर दो। इसलिए रेखाओं के बीच की दूरी दो इकाई है। ध्यान रहे, दोनों समीकरणों में एक्स और वाई के गुणांक पहले एक जैसे कर लें।"),
Q("(1, 2), (4, 6) और (7, 2) शीर्ष वाले त्रिभुज का केंद्रक ज्ञात कीजिए।","((1+4+7)/3, (2+6+2)/3) = (4, 10/3)","केंद्रक के निर्देशांक तीनों शीर्षों के निर्देशांकों के औसत होते हैं। एक्स के लिए, एक जमा चार जमा सात बराबर बारह, भाग तीन, यानी चार। वाई के लिए, दो जमा छह जमा दो बराबर दस, भाग तीन। इसलिए केंद्रक चार, दस बटा तीन है।"),
C("⚠️","सामान्य ग़लतियाँ और सुझाव",["ढाल में चिह्न की ग़लती","द्वि-बिंदु रूप में क्रम उलटना","दूरी सूत्र में मापांक भूलना","संरेख जाँच में एक जोड़ी ही देखना"],"इस अध्याय में सबसे आम ग़लती चिह्नों की होती है। ढाल निकालते समय दोनों बिंदुओं का क्रम एक जैसा रखिए। लंब रेखा की शर्त में ऋणात्मक व्युत्क्रम लेना भूलना भी आम बात है। बिंदु से दूरी में मापांक लगाइए, वरना ऋणात्मक उत्तर आ सकता है। अंत में हर उत्तर को किसी आसान बिंदु पर रखकर जाँच लीजिए कि वह समीकरण को संतुष्ट करता है या नहीं। इससे ग़लती वहीं पकड़ में आ जाएगी।"),
],7)
